import{_ as a,o as t,c as r,a5 as s}from"./chunks/framework.DrDMl0tG.js";const u=JSON.parse('{"title":"Server Example: Fluid Stream","description":"","frontmatter":{},"headers":[],"relativePath":"sections/examples/server/fluid_stream.md","filePath":"sections/examples/server/fluid_stream.md"}'),i={name:"sections/examples/server/fluid_stream.md"};function l(o,e,d,h,n,c){return t(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="server-example-fluid-stream" tabindex="-1">Server Example: Fluid Stream <a class="header-anchor" href="#server-example-fluid-stream" aria-label="Permalink to &quot;Server Example: Fluid Stream&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>A stream flows down a channel 20 m long and 0.8 m deep, past a post, under air (<a href="./../../Fluids.html">Fluids</a>). Its current is the velocity of the water&#39;s <code>FluidVolume</code>.</p><ul><li>Crates, logs and beach balls float off with the stream. The water&#39;s drag carries them toward its speed, and the still air over the stream holds back what they lift above it: in a stream of 0.8 m/s, after 15 s a beach ball, riding mostly above the water, drifts at about 0.65 m/s and a crate at about 0.77 m/s. A log that meets the post wraps against it.</li><li>Bricks on the stony bed stay put in a gentle stream. Past about 2.1 m/s the water&#39;s push beats the friction of the bed on what the water leaves of their weight, and they slide along.</li></ul><p>What reaches the end of the channel drops back in at its start, and the example prints how many bodies the stream has carried down.</p><h2 id="controlling-the-stream" tabindex="-1">Controlling the stream <a class="header-anchor" href="#controlling-the-stream" aria-label="Permalink to &quot;Controlling the stream&quot;">​</a></h2><p>The example adds a slider, <code>Stream speed [m/s]</code>, from 0 to 3 m/s (<code>RaisimServer::addSlider()</code>). The rayrai TCP viewer shows it in its <strong>Controls</strong> window, at the lower right of the view. Drag it to change the current. Each step, the example reads it with <code>RaisimServer::getSlider()</code> and sets the water&#39;s velocity with <code>World::setFluidVolume()</code>.</p><h2 id="target" tabindex="-1">Target <a class="header-anchor" href="#target" aria-label="Permalink to &quot;Target&quot;">​</a></h2><p>CMake target: <code>fluid_stream</code>.</p><h2 id="run" tabindex="-1">Run <a class="header-anchor" href="#run" aria-label="Permalink to &quot;Run&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build-examples/examples/fluid_stream</span></span></code></pre></div><p>Connect <code>rayrai_tcp_viewer</code> to port 8080. On Windows, run <code>build-examples/bin/fluid_stream.exe</code>.</p><h2 id="details" tabindex="-1">Details <a class="header-anchor" href="#details" aria-label="Permalink to &quot;Details&quot;">​</a></h2><ul><li>The channel is a <code>FluidVolume</code> bounded by its banks, from the bed up to its surface, with the current along x. The bed&#39;s friction is 1.2, that of a stony bed.</li><li>The TCP viewer draws the water of the channel: the server sends it the world&#39;s volumes of liquid.</li><li>The scene lives in <code>include/fluid_stream.hpp</code>, which it shares with <a href="./fluid_stream_anymal.html">Fluid Stream with ANYmal</a>.</li></ul>',14)])])}const p=a(i,[["render",l]]);export{u as __pageData,p as default};
